from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-N03"><div class="chap"><div class="chap-head"><div class="code">N03 · N-07-Néphrologie</div><h1>Syndrome néphritique chronique</h1><span class="status">Monographie pédagogique · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#n03-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="N03">'''
a+=sec('question','Une anomalie ancienne, une décision actuelle', '''<p><b>Vignette fictive.</b> Une personne consulte pour renouveler un traitement antihypertenseur. Depuis huit mois, ses examens montrent une protéinurie à prédominance albuminurique et une hématurie microscopique ; le débit estimé est passé de 68 à 51 mL/min/1,73 m². Elle ne ressent aucune douleur. Le dossier porte simplement la mention « néphrite chronique ». Faut-il renouveler sans changement, prescrire un corticoïde ou proposer une dialyse ?</p><p>La première tâche consiste à vérifier les mesures, leur chronologie et les traitements. Il faut ensuite apprécier la vitesse de dégradation, rechercher une complication et établir la cause de l’atteinte glomérulaire. L’absence de symptômes n’écarte pas le risque ; le caractère chronique ne démontre pas que toute lésion soit inactive. Une protéinurie persistante peut traduire une maladie encore active, une cicatrice ou les deux. La distinction change le bilan et le traitement.</p>'''+key('Distinguer quatre questions : quel syndrome, quelle cause, quelle activité et quel risque de progression ?'),('EU-SYNDROMES','CH-SGN-REF','INT-CKD-RISK'))
a+=sec(1,'1. Définition : un syndrome glomérulaire dans la durée', '''<p>Le syndrome de glomérulonéphrite chronique associe une <b>protéinurie glomérulaire persistante</b>, avec ou sans hématurie, hypertension et diminution de fonction rénale. La présentation peut rester discrète. Dans le tableau pédagogique du CUEN, toutes les glomérulopathies chroniques peuvent produire ce profil : il ne correspond donc pas à une maladie unique ni à une seule lésion histologique.</p><p>Le terme <b>chronique</b> exige une histoire documentée. Pour la maladie rénale chronique, les critères formels reposent sur une anomalie de structure ou de fonction présente au moins trois mois et ayant des conséquences pour la santé. Les valeurs antérieures, l’urine, l’imagerie et parfois la fibrose ou l’atrophie sur biopsie apportent des preuves. Un seul débit bas ne permet pas d’affirmer la chronicité ; une atteinte aiguë ou une aggravation aiguë sur maladie chronique reste possible.</p><p>Le syndrome glomérulaire et la maladie rénale chronique répondent à deux questions différentes. Le premier décrit un profil de maladie ; la seconde décrit une durée et un retentissement rénal classés selon cause, filtration et albuminurie. Une maladie glomérulaire peut exister avec un débit encore préservé. Inversement, toute maladie rénale chronique n’est pas glomérulaire, et toute lésion glomérulaire ne relève pas administrativement de N03.</p><p>Dans la CIM-10-GM suisse consultée, N03 inclut les termes glomérulopathie, glomérulonéphrite et néphrite chroniques. Les exclusions comprennent la néphrite tubulo-interstitielle chronique N11, la glomérulonéphrite sclérosante diffuse classée N18 et le syndrome néphritique sans précision N05. Les suffixes morphologiques se choisissent après le diagnostic ; ils ne doivent pas devenir l’objectif du bilan.</p>''',('EU-SYNDROMES','INT-CKD-DEF','CH-CIM'))
a+=sec(2,'2. Épidémiologie : préciser ce que l’on compte', '''<p>Le Pocketguide 2025 de la Société suisse de néphrologie estime qu’environ un adulte sur dix en Suisse présente une maladie rénale chronique, souvent non diagnostiquée. Ce chiffre concerne l’ensemble de la maladie rénale chronique. Il ne mesure ni l’incidence du syndrome néphritique chronique N03, ni celle d’une glomérulonéphrite particulière. Les sources retenues n’apportent pas de taux national direct de N03 ; aucun chiffre de dialyse ou de biopsie ne lui est substitué.</p><p>La fréquence observée des maladies glomérulaires dépend du dépistage, de l’indication et de l’accès à la biopsie, de l’âge et des maladies associées. Une série de biopsies décrit des personnes sélectionnées pour un examen, tandis qu’une enquête de population inclut aussi des atteintes peu symptomatiques. Une fréquence de lésion parmi des biopsies ne s’applique donc pas à toutes les personnes ayant une protéinurie.</p><p>La néphropathie à IgA, les maladies auto-immunes ou infectieuses, les anomalies du collagène IV et les maladies à dépôts participent au diagnostic différentiel. Leur poids varie avec le contexte. Un antécédent familial, un lupus connu, une infection persistante ou une gammapathie modifie la probabilité de départ. Le diabète et l’hypertension sont également fréquents dans la population ; leur présence ne suffit pas à expliquer une hématurie glomérulaire active ou une trajectoire atypique.</p><p>La conséquence pratique est de dépister les personnes à risque, de quantifier les anomalies et d’établir la cause. Les données générales justifient une vigilance ; elles ne donnent pas le diagnostic individuel.</p>''',('CH-SGN-DEF','EU-SYNDROMES','INT-GN-MPGN','EU-ALPORT-GEN'))
a+=sec(3,'3. Physiopathologie : perméabilité, inflammation et perte néphronique', '''<p>Le filtre glomérulaire normal associe endothélium, membrane basale et podocytes. Il sépare le sang de l’espace urinaire tout en permettant la filtration. Une altération peut augmenter le passage de protéines et permettre celui d’érythrocytes. La protéinurie à prédominance albuminurique et les hématies dysmorphiques donnent ainsi des indices sur le compartiment atteint ; ils ne nomment pas à eux seuls la maladie.</p><p>Les lésions peuvent associer dépôts immunitaires, prolifération cellulaire, atteinte structurale et cicatrices. Une prolifération active et une sclérose ne sont pas synonymes. La sclérose remplace une partie ou la totalité du glomérule par du matériel cicatriciel ; la fibrose et l’atrophie tubulo-interstitielle renseignent sur la chronicité et le pronostic. Le compte rendu de biopsie doit être interprété avec la clinique et la fonction, car un prélèvement peut montrer simultanément activité et dommages anciens.</p>'''+figure('podocytes')+'''<p>La perte de néphrons modifie la charge imposée aux néphrons restants. Le risque évolutif ne dépend donc pas seulement de la persistance de l’agression initiale : l’hémodynamique, la pression artérielle et la protéinurie participent également aux conséquences de la maladie. La néphroprotection vise ces voies, tandis qu’un traitement étiologique vise le mécanisme responsable lorsqu’il est identifié et accessible à un traitement.</p><p>Un aspect de sclérose segmentaire et focale peut avoir plusieurs significations. La microphotographie ci-dessous, attribuée à une variante hilaire par sa source, montre un type de lésion, sans établir un mécanisme primaire ou secondaire. Une photographie PAS ne suffit pas à décider d’une immunosuppression.</p>'''+figure('fsgs'),('NORMAL-FILTRE','EU-HISTO','INT-CKD-TX','INT-GN-GENERAL'))
a+=sec(4,'4. Démarche clinique : commencer par la trajectoire et la gravité', '''<p><b>Rechercher une aggravation.</b> Comparer créatinine, débit, pression, protéinurie et diurèse aux valeurs précédentes. Une oligurie nouvelle, une dyspnée, une surcharge, une hypertension avec retentissement ou une chute rapide de fonction imposent une évaluation accélérée, souvent urgente. Un syndrome pulmonaire–rénal possible ne relève pas du prochain contrôle annuel. Le mot « chronique » dans le dossier ne protège pas d’une complication aiguë.</p><p><b>Confirmer et caractériser.</b> Vérifier recueil urinaire, infection, contamination et méthode de quantification. Distinguer albumine et protéines totales ; demander un sédiment morphologique lorsque l’origine glomérulaire est discutée. Établir la chronicité par des preuves, sans attendre trois mois lorsqu’un tableau menaçant nécessite une prise en charge immédiate.</p><p><b>Rechercher la cause et l’activité.</b> Reprendre l’anamnèse, les maladies systémiques, les médicaments, les antécédents familiaux et les examens antérieurs. Le néphrologue choisit les investigations susceptibles de modifier la décision : immunologie orientée, recherche infectieuse, génétique ou biopsie. Une maladie déjà connue peut coexister avec une autre atteinte ; la discordance entre diagnostic ancien et évolution actuelle mérite une réévaluation.</p><p><b>Évaluer le risque et organiser les soins.</b> Classer selon cause, débit et albuminurie, puis intégrer leur évolution et les complications. La SGN recommande l’orientation notamment devant hématurie glomérulaire, cause inconnue, progression ou albuminurie importante. Le compte rendu doit préciser le prochain contrôle, les traitements et les signes qui justifient un contact anticipé.</p>''',('CH-HUG-ORIENT','CH-SGN-REF','INT-CKD-DEF','INT-CKD-RISK','INT-GN-GENERAL'))
a+=sec(5,'5. Anamnèse : reconstituer une maladie souvent silencieuse',table(['Domaine','Questions','Interprétation'],[['Chronologie','Première protéinurie, hématurie, créatinine et pression connues ; épisodes aigus ; résultats datés','Prouver la durée et repérer une accélération ou un événement réversible.'],['Signes rénaux','Urines rouges, mousse, diurèse, œdèmes, prise de poids','Orienter le retentissement ; la mousse ou la couleur ne quantifient pas les protéines.'],['Maladie systémique','Purpura, douleurs articulaires, atteinte cutanée, ORL, respiratoire ou générale','Discuter maladie auto-immune, vascularite ou infection selon l’ensemble du tableau.'],['Infection','Fièvre prolongée, foyer connu, exposition et antécédents viraux pertinents','Une infection peut entretenir ou imiter une glomérulopathie immune.'],['Famille','Hématurie, dialyse, âge de survenue, audition et yeux','Orienter collagène IV ou autre maladie héréditaire, sans diagnostic sur le seul arbre familial.'],['Médicaments','AINS, automédication, compléments, produits naturels, traitements récents et observance','Détecter toxicité, interaction, interruption ou modification hémodynamique.'],['Événements intercurrents','Vomissements, diarrhée, fièvre, chirurgie, changement diurétique','Chercher déplétion et risque d’aggravation aiguë ; prévoir une reprise sécurisée des traitements.'],['Vie quotidienne','Alimentation, sel, activité, tabac, travail, capacité à suivre le plan','Adapter les soins aux possibilités et préférences ; éviter une prescription théorique inapplicable.'],['Grossesse et reproduction','Grossesse actuelle, projet, contraception et conseil génétique si pertinent','Revoir tôt les traitements, notamment bloqueurs du système rénine–angiotensine.']])+'''<p>Une anamnèse négative n’exclut pas une maladie active. À l’inverse, une plainte non spécifique ne suffit pas à prouver une complication urémique. Les médicaments réellement pris, y compris ceux achetés sans ordonnance, et les dates des résultats font partie du diagnostic.</p>''',('CH-HUG-ORIENT','EU-SYNDROMES','EU-ALPORT-GEN','INT-CKD-DRUG','FI-RAMIPRIL','FI-FORXIGA'))
a+=sec(6,'6. Examen clinique : mesurer le retentissement', '''<p>Mesurer la pression avec une méthode fiable et répétable ; rechercher une hypotension orthostatique si les symptômes, l’âge ou les traitements le suggèrent. La cible thérapeutique ne se discute qu’après avoir précisé la technique et la tolérance. La recommandation suisse de 120–129 mmHg systolique chez l’adulte se module selon fragilité et comorbidités ; elle ne se transpose pas directement à l’enfant.</p><p>Évaluer poids et évolution pondérale, œdèmes, signes de congestion et état d’hydratation. Une prise de poids peut traduire une rétention, tandis qu’une baisse de pression avec pertes digestives peut signaler une déplétion. L’œdème ne prouve ni la quantité d’albumine perdue ni une indication d’albumine intraveineuse. Une dyspnée exige de rechercher sa cause et sa gravité plutôt que d’augmenter automatiquement le diurétique.</p><p>L’examen recherche les indices suggérés par l’histoire : peau et purpura, articulations, signes infectieux ou systémiques, régions lombaires et appareil urinaire selon les symptômes. Une atteinte respiratoire, une altération neurologique ou un état général qui se dégrade modifie la priorité. Les manifestations auditives et oculaires peuvent orienter une maladie du collagène IV ; l’absence de plainte ne remplace pas un examen spécialisé lorsqu’il est indiqué.</p><p>Chez l’enfant, suivre croissance et développement, interpréter pression et fonction selon les références pédiatriques et organiser la continuité des soins. Chez l’adulte âgé, évaluer aussi chutes, fragilité, nutrition et charge médicamenteuse. L’examen termine une synthèse : stabilité, retentissement, arguments de cause et éléments encore non expliqués.</p>''',('CH-SGN-PEC','CH-HUG-ORIENT','INT-CKD-TX','INT-CKD-KRT','EU-ALPORT-GEN'))
a+=sec(7,'7. Syndromes et classifications : garder plusieurs axes',table(['Axe','Ce qu’il décrit','Limite'],[['Syndrome glomérulaire chronique','Protéinurie persistante ± hématurie, hypertension, baisse de fonction','Ce profil ne nomme pas l’étiologie.'],['Syndrome néphritique aigu','Installation brutale avec hématurie et retentissement rénal/hydrosodé','Peut survenir sur une maladie chronique.'],['Progression rapide','Dégradation fonctionnelle sur un temps court, avec suspicion de maladie glomérulaire active','Urgence de bilan ; ne pas attendre une définition administrative de chronicité.'],['Syndrome néphrotique associé','Protéinurie importante et hypoalbuminémie selon population et référentiel','Risques et prise en charge propres ; œdème seul insuffisant.'],['Classification CGA','Cause, catégorie de débit G et albuminurie A','G1 ou G2 isolés sans marqueur ne définissent pas une MRC.'],['Histologie','Prolifération, dépôts, sclérose, fibrose et distribution des lésions','Un pattern ne suffit pas toujours à définir une maladie.']])+'''<p>La classification de maladie rénale chronique comporte G1 ≥90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29 et G5 &lt;15 mL/min/1,73 m². L’albuminurie est A1 &lt;30, A2 30–300 et A3 &gt;300 mg/g de créatinine, avec des bornes approximatives correspondantes en mg/mmol. Les méthodes et unités doivent rester visibles. Une catégorie ne remplace pas la pente d’évolution.</p><p>La morphologie ajoute un autre axe : segmentaire désigne une partie du glomérule, globale sa totalité ; focale et diffuse décrivent la distribution entre glomérules. Une lésion membranoproliférative constitue un pattern qui peut résulter de causes différentes. La bonne synthèse associe ces axes au lieu de transformer le dernier mot du compte rendu en diagnostic et en traitement complets.</p>''',('EU-SYNDROMES','EU-HISTO','INT-CKD-DEF','INT-GN-MPGN'))
save('a',a)
b=sec(8,'8. Diagnostic positif : quatre niveaux de preuve', '''<div class="alert"><b>Critères de raisonnement.</b> Établir une anomalie glomérulaire, documenter sa persistance, rechercher la cause et apprécier activité/retentissement. Aucun test unique ne remplace ces quatre niveaux.</div><p><b>Le signe.</b> La protéinurie est dépistée puis quantifiée ; sa composante albuminurique soutient une atteinte du filtre. Une bandelette positive pour le sang doit être confrontée à la présence d’hématies. Les HUG utilisent notamment plus de 60 % de dysmorphie, plus de 5 % d’acanthocytes ou des cylindres hématiques pour orienter l’origine glomérulaire, avec des limites de sensibilité et d’interprétation. Une hématurie peut manquer dans certaines présentations chroniques.</p><p><b>La durée.</b> Les anomalies anciennes et les contrôles apportent une preuve de chronicité. Une petite taille rénale ou une fibrose peut la soutenir, mais ne doit pas faire négliger une composante aiguë surajoutée. La maladie rénale chronique peut être définie par des marqueurs persistants même avec un débit supérieur à 60 ; le critère de débit inférieur à 60 pendant au moins trois mois constitue une autre voie diagnostique.</p><p><b>La cause.</b> Elle vient de l’ensemble clinique, biologique, génétique et histologique. Une IgA rénale ne se diagnostique pas sur l’IgA sérique ; la biopsie est nécessaire. Chez l’adulte ayant une IgA possible et une protéinurie d’au moins 0,5 g/j, KDIGO 2025 propose de considérer une biopsie si elle est réalisable. Une cause héréditaire documentée peut modifier cette démarche, mais une évolution atypique peut justifier de rechercher une maladie associée.</p><p><b>L’activité et le risque.</b> Une protéinurie persistante ne démontre pas seule une inflammation sensible aux corticoïdes. La biopsie peut préciser activité et cicatrices ; la trajectoire de fonction, la pression et les protéines contribuent au pronostic. La conclusion doit dire ce qui est confirmé, probable ou encore indéterminé.</p>''',('EU-SYNDROMES','CH-HUG-DEF','CH-HUG-ORIENT','INT-CKD-DEF','INT-IGA-DX','EU-ALPORT-GEN','EU-HISTO'))
b+=sec(9,'9. Explorations : choisir les examens qui changent une décision', '''<p>Le bilan commence par les valeurs antérieures, la mesure de pression, la créatinine et le débit estimé, l’albuminurie/protéinurie et le sédiment. La numération, les électrolytes, l’albumine et les autres paramètres sont adaptés au retentissement. En maladie rénale plus avancée, rechercher notamment anémie, troubles du potassium, acidose et troubles minéraux ; une anomalie n’est pas automatiquement d’origine rénale.</p><p>L’immunologie répond à des hypothèses : complément, autoanticorps ou recherche de composant monoclonal selon présentation et tissu. Devant un pattern membranoprolifératif, rechercher infection, maladie auto-immune, immunoglobuline monoclonale ou dysrégulation du complément selon le profil d’immunofluorescence. Un C3 normal ne ferme pas toutes ces hypothèses, et un C3 bas ne donne pas une étiologie unique.</p><p>L’échographie examine dimensions, parenchyme et voies excrétrices ; elle peut identifier une obstruction ou des indices de chronicité. Elle ne montre pas les dépôts glomérulaires microscopiques. Le choix d’une biopsie dépend de l’utilité attendue, du risque, des conditions du geste et de l’accord éclairé. Les études optique, immunofluorescente et parfois électronique répondent à des questions complémentaires.</p><p>La fonction calculée a des limites lorsque la créatinine change rapidement, lorsque la masse musculaire est inhabituelle ou lorsqu’une décision exige une grande précision. Le débit combinant créatinine et cystatine C, voire une mesure de filtration, peut alors être utile selon la question. L’équation doit être validée pour la population ; ne pas appliquer un calcul d’adulte à l’enfant. La pharmacologie doit aussi vérifier si la FI exprime une clairance ou un débit indexé.</p>''',('CH-SGN-DEF','CH-SGN-PEC','INT-GN-GENERAL','INT-GN-MPGN','INT-CKD-DEF','INT-CKD-DRUG'))
b+=sec(10,'10. Arbre diagnostique et diagnostics différentiels',table(['Étape','Éléments discriminants','Suite logique'],[['1. Anomalie réelle ?','Prélèvement, confirmation des cellules, analyte et unité des protéines','Contrôler contamination, interférence et infection ; ne pas conclure sur la seule bandelette.'],['2. Profil glomérulaire ?','Albuminurie, acanthocytes/cylindres, signes rénaux ou systémiques','Bilan néphrologique ; une cause urologique peut coexister selon risque.'],['3. Aigu, chronique ou aigu sur chronique ?','Résultats datés, vitesse de chute, événements intercurrents, imagerie/histologie','Une aggravation nouvelle exige une recherche de cause réversible et d’activité.'],['4. Cause glomérulaire ?','IgA, lupus/vascularite, infection, collagène IV, dépôts monoclonaux ou complément','Examens ciblés ; génétique et/ou biopsie selon contexte.'],['5. Autre compartiment ?','Obstruction, maladie tubulo-interstitielle, médicaments, profil diabétique ou vasculaire','Reconsidérer le diagnostic plutôt que conserver une étiquette ancienne sans preuve.'],['6. Risque et traitement ?','Cause, activité, cicatrices, débit, albuminurie, pente, comorbidités','Néphroprotection et traitement de cause individualisés ; suivi documenté.']])+'''<p>Une hypertension de longue durée et un diabète peuvent coexister avec une glomérulopathie. Une hématurie glomérulaire, une maladie systémique ou une évolution inhabituelle empêchent d’attribuer tout le tableau à ces seuls antécédents. Une maladie du collagène IV peut produire une sclérose secondaire ; un pattern membranoprolifératif peut masquer plusieurs causes. Le diagnostic différentiel porte donc à la fois sur le compartiment, le mécanisme et la temporalité.</p><p>La baisse aiguë de fonction peut également venir d’une déplétion, d’un obstacle ou d’un médicament. La reconnaître ne dispense pas de suivre la maladie chronique, mais évite de confondre un événement potentiellement réversible et une perte rénale inexorable. Les données de la biopsie restent interprétées dans cette histoire complète.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT','CH-HUG-URO','EU-SYNDROMES','INT-CKD-DEF','INT-CKD-DRUG','INT-GN-MPGN','EU-ALPORT-GEN'))
b+=sec(11,'11. Prise en charge : protéger le rein et traiter la cause', '''<p><b>Organiser le niveau de soins.</b> Le syndrome glomérulaire chronique nécessite une évaluation néphrologique pour préciser cause, activité et risque. Une complication aiguë change le délai. Les examens de cause ne doivent pas retarder la stabilisation d’une surcharge respiratoire, d’une hypertension avec atteinte d’organe ou d’un trouble métabolique menaçant. Une dialyse ne se décide pas sur le code N03 ni sur un chiffre isolé de créatinine.</p><p><b>Réduire les facteurs de progression.</b> Le Pocketguide suisse 2025 retient une alimentation adaptée, moins de 5 g de sel par jour, une activité physique visant environ 150 minutes par semaine selon les capacités, l’arrêt du tabac et la gestion du poids. L’apport protéique de 0,8 g/kg/j concerne surtout les adultes avec maladie rénale chronique ; chez l’enfant, la croissance interdit une transposition automatique, et la fragilité peut nécessiter d’autres objectifs nutritionnels. Un diététicien aide à adapter potassium, énergie et protéines aux résultats.</p><p><b>Contrôler la pression et les protéines.</b> La SGN propose une cible systolique de 120–129 mmHg, adaptée à la personne ; elle explicite que KDIGO préconise moins de 120 mmHg si une mesure standardisée est utilisée et si la cible est tolérée. Ne pas poursuivre un nombre au prix de chutes ou d’hypotension symptomatique. Le blocage rénine–angiotensine est utilisé à dose autorisée et tolérée dans les situations appropriées, sans association IEC–ARA. Contrôler pression, créatinine et potassium dans les deux à quatre semaines suivant introduction ou augmentation, plus tôt selon risque.</p><p><b>Choisir les produits dans le cadre suisse.</b> Les inhibiteurs SGLT2 ont une place dans certaines maladies rénales chroniques, y compris sans diabète. Une recommandation de classe dès un débit de 20 ne signifie pas que tous les produits suisses peuvent être débutés à ce seuil : Forxiga ne doit pas être introduit sous 25 selon sa FI consultée et n’est pas recommandé dans la néphropathie sous immunosuppresseur. Le détail des cinq produits retenus est donné dans Pharmacologie, avec leurs indications et limites propres.</p><p><b>Traiter l’étiologie démontrée.</b> Une maladie immune active, une infection, une anomalie génétique et des cicatrices avancées ne reçoivent pas le même traitement. La décision d’immunomodulation est spécialisée et fondée sur la maladie, l’activité, les risques infectieux et le bénéfice attendu. La néphroprotection reste nécessaire lorsqu’un traitement de cause est instauré ; elle ne signifie pas qu’une cause encore traitable peut être négligée. À l’inverse, le mot « glomérulonéphrite » seul n’autorise pas une corticothérapie empirique prolongée.</p>''',('CH-SGN-PEC','CH-SGN-REF','INT-CKD-TX','INT-CKD-KRT','FI-RAMIPRIL','FI-COSAAR','FI-FORXIGA','EU-HISTO','INT-GN-MPGN'))
b+=sec(12,'12. Prévention, suivi et pronostic : suivre plus qu’un résultat', '''<p>Le suivi mesure au moins pression, filtration et albuminurie/protéinurie, ainsi que symptômes, poids, tolérance et événements intercurrents. KDIGO propose au minimum une évaluation annuelle de filtration et d’albuminurie dans la maladie rénale chronique, et plus souvent lorsque le risque ou une décision thérapeutique le justifie. Ce minimum ne décrit pas le contrôle après modification d’un médicament ni celui d’une maladie glomérulaire active.</p><p>Un changement de débit supérieur à 20 % sur un contrôle, une diminution supérieure à 30 % après un traitement modifiant l’hémodynamique, ou un doublement du rapport albumine/créatinine dépasse les variations attendues et appelle une évaluation. Ce sont des signaux pour vérifier prélèvement, médicaments, volume, obstacle et activité de maladie, pas une preuve automatique de progression irréversible. Une baisse plus modeste peut aussi être pertinente si la clinique est inquiétante.</p><p>Chez les personnes avec maladie rénale chronique G3–G5, une équation validée peut estimer le risque de défaillance rénale. KDIGO propose notamment qu’un risque à cinq ans de 3–5 % contribue à décider l’orientation néphrologique, qu’un risque à deux ans supérieur à 10 % aide à planifier les soins multidisciplinaires et qu’un risque supérieur à 40 % aide à préparer la suppléance. Ces repères s’ajoutent aux critères suisses et à la clinique ; ils ne doivent pas retarder une consultation devant hématurie glomérulaire ou maladie active. Ne pas appliquer un outil G3–G5 à G1–G2.</p><p>Les complications recherchées varient avec la cause et le stade : maladie cardiovasculaire, troubles du potassium, acidose, anémie, anomalies minérales, dénutrition et retentissement psychosocial. En maladie avancée, présenter transplantation, dialyse et soins conservateurs complets selon les préférences et la situation. La préparation et le début effectif de suppléance sont deux décisions distinctes.</p><p>La prévention comporte l’évitement des néphrotoxiques inutiles, la revue de l’automédication, la compréhension des traitements et un plan en cas de maladie aiguë. Toute interruption temporaire doit avoir des consignes de contrôle et de reprise ; une suspension oubliée peut priver durablement d’un traitement utile. Le patient doit connaître son interlocuteur et les signes qui imposent un contact anticipé.</p>''',('CH-SGN-PEC','CH-SGN-REF','INT-CKD-RISK','INT-CKD-DRUG','INT-CKD-KRT','INT-CKD-TX'))
b+=sec(13,'13. Points clés et entraînement clinique', '''<ul><li>Un syndrome glomérulaire chronique ne nomme pas sa cause.</li><li>Protéines, sédiment, pression et trajectoire de fonction sont complémentaires.</li><li>Chronique ne signifie ni stable, ni entièrement cicatriciel, ni toujours irréversible.</li><li>Une biopsie précise mécanisme, activité et dommages ; un pattern ne vaut pas automatiquement étiologie.</li><li>La cible de pression suppose méthode, tolérance et population précisées.</li><li>La prescription respecte la FI du produit exact et un suivi de sécurité.</li><li>Un risque calculé aide à organiser les soins ; il ne remplace pas les signes d’alerte.</li></ul><p>Les cas et quiz sont des exercices originaux fictifs. Leur lien pédagogique avec PROFILES 2017 concerne notamment les marqueurs de fonction rénale SSP161, le sédiment SSP164, la protéinurie SSP173, l’histologie/génétique SSP159 et l’hématurie SSP64. Ils ne sont ni des questions fédérales reproduites ni une correspondance officielle CIM–PROFILES. Les exigences MEBEKO lues portent sur l’examen 2026.</p>'''+''.join('<p>'+w('cas-'+str(i),'Cas clinique '+str(i)+' — analyser la décision')+'</p>' for i in range(1,5)),('CH-PROFILES','CH-MEBEKO','EU-SYNDROMES','INT-CKD-RISK'))
b+=sec(14,'14. Pièges : les mots qui ferment trop tôt le raisonnement',table(['Raccourci','Correction utile'],[['Chronique = attendre le prochain contrôle','Une complication aiguë ou une progression rapide impose une réévaluation immédiate.'],['Débit normal = rein normal','Une albuminurie, un sédiment ou une histologie pathologique persistants peuvent définir une maladie rénale.'],['Protéinurie persistante = inflammation active','Distinguer activité, cicatrices et conséquences hémodynamiques.'],['Sclérose segmentaire = maladie primitive à corticoïdes','Le pattern peut être secondaire ou génétique ; interpréter le contexte.'],['MPGN = étiologie','Chercher infection, immunité, composant monoclonal ou complément selon le tissu.'],['Une cible tensionnelle vaut quelle que soit la mesure','Distinguer mesure standardisée, cible suisse et tolérance individuelle.'],['Toute hausse de créatinine sous IEC prouve une toxicité irréversible','Évaluer amplitude, délai, volume, médicaments, potassium et cause.'],['Un iSGLT2 débute toujours à 20','La recommandation de classe et la FI du produit exact sont distinctes.'],['Œdème = supplément de potassium nécessaire sous diurétique','La maladie rénale et les traitements peuvent aussi augmenter le potassium ; mesurer et adapter.'],['G5 = dialyse immédiate','Décision selon symptômes, retentissement, biologie, préférences et options.']])+key('Une bonne étiquette est une conclusion provisoire qui reste confrontée aux données nouvelles.'),('INT-CKD-DEF','INT-CKD-RISK','INT-CKD-TX','INT-GN-MPGN','EU-HISTO','FI-FORXIGA','FI-LASIX-PO','INT-CKD-KRT'))
b+='</div></div>';save('b',b)
print('N03 :14points cliniques écrits ; relecture requise.')
